// PREFILTRO DE COSTO (2026-08-27).
// La compuerta de W2 ya decidía bien a quién responder, pero decidía DESPUÉS de
// pagar el clasificador Haiku. Medición real de 7 días: 103 mensajes entrantes,
// 0 respondidos — el 100% del gasto de clasificación terminó en silencio.
//
// Este nodo NO cambia a quién le responde Nai. Solo evita pagarle al modelo por
// mensajes cuyo destino ya es conocido sin leerlos. Ante la duda, deja pasar:
// un falso positivo cuesta unos centavos, un falso negativo es un cliente perdido.
const g = $json;
const texto = ($('Upsert contacto + conversación').item.json.final_text || '').toLowerCase();

// Silencio garantizado, sin importar lo que diga el mensaje:
if (g.bloqueado) {
  return { json: { ...g, clasificar: false, motivo: 'contacto personal en personal_blocklist' } };
}
if (!g.prod && !g.en_allowlist) {
  return { json: { ...g, clasificar: false, motivo: 'modo test: el número no está en test_allowlist' } };
}

// Conversación ya abierta o cliente con póliza: siempre vale la pena pensar.
if (g.already_active) return { json: { ...g, clasificar: true, motivo: 'conversación ya abierta' } };
if (g.known_client) return { json: { ...g, clasificar: true, motivo: 'cliente con póliza' } };

// Desconocido: solo se paga el clasificador si hay alguna señal léxica de seguros.
// Deliberadamente amplia — incluye jerga venezolana y errores de escritura comunes.
// Si esta lista se queda corta, el síntoma es silencio ante un cliente real: al
// agregar términos, pecar de generoso.
const SENALES = [
  'seguro', 'asegur', 'poliza', 'póliza', 'rcv', 'cobertura', 'prima', 'siniestr',
  'cotiz', 'presupuest', 'precio', 'cuanto', 'cuánto', 'costo', 'vale', 'tarifa',
  'choque', 'chocaron', 'chocar', 'accidente', 'grua', 'grúa', 'volco', 'volcó',
  'robaron', 'robo', 'hurto', 'perdida total', 'pérdida total', 'deducible',
  'carro', 'moto', 'vehiculo', 'vehículo', 'camioneta', 'caucho', 'parachoque',
  'salud', 'hospital', 'clinica', 'clínica', 'medic', 'consulta', 'emergencia',
  'embaraz', 'parto', 'cesarea', 'cesárea', 'funerario', 'funeral', 'sepelio',
  'vida', 'hogar', 'casa', 'viaje', 'apartament',
  'pago', 'pagar', 'cuota', 'financ', 'renov', 'vence', 'venci', 'cancelar',
  'reclamo', 'reclam', 'cita', 'agendar', 'documento', 'cedula', 'cédula',
  'carnet', 'titulo', 'título', 'placa', 'reposo', 'factura', 'constancia',
  'nairobi', 'corredora', 'aseguradora', 'mapfre', 'altamira', 'mercantil',
  'caracas', 'oceanica', 'oceánica', 'hispana', 'atrio', 'constitucion', 'constitución',
];
const hay = SENALES.some((s) => texto.includes(s));
// Mensajes muy cortos sin señal ("ok", "hola", un emoji) son el caso típico del
// conocido que saluda: no se clasifican.
return {
  json: {
    ...g,
    clasificar: hay,
    motivo: hay
      ? 'desconocido con señal de seguros: vale clasificar'
      : 'desconocido sin señal de seguros: silencio sin gastar en el modelo',
  },
};
